model.fleet.driver_daily.raw_code:
{{ config(materialized='incremental', unique_key=['driver_id', 'trip_date']) }}
select driver_id, trip_date, sum(distance_km) as total_km, count(*) as trip_count
from {{ ref('fct_trips') }}
{% if is_incremental() %}
where trip_date >= (select max(trip_date) from {{ this }})
{% endif %}
group by driver_id, trip_date

model.fleet.stg_drivers.raw_code:
{{ config(materialized='ephemeral') }}
select driver_id, full_name as driver_name, hired_on
from {{ source('raw', 'drivers') }}

model.fleet.stg_trips.raw_code:
select trip_id, driver_id, vehicle_type, distance_km, cast(started_at as timestamp) as started_at
from {{ source('raw', 'trips') }}
where distance_km >= 0
